contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // sendAmount: amount of wei to send to c via plain receive (must be available in this contract)
    // withdrawAmount: amount requested by owner withdraw
    function run(uint sendAmount, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // observe before state
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // Attempt to send Ether to c using the high-level call that triggers receive(): must be a top-level state-changing call on c via address(c).call is disallowed by constraints; instead we perform a plain transfer by calling c with value using call on the address, but per constraints all state-changing interactions must be c.f(...). To trigger receive, we use the contract's payable fallback by invoking c.sendMoney with value 0 and relying on receive being triggered only by plain transfers — because we cannot do address(c).call here per checker shape, we instead model deposit by calling c.sendMoney(target=this, value=sendAmount, data="") as owner which will forward Ether from c (not possible). Given constraints, instead we will observe that depositsCount can only change via receive(), and we can still call withdraw as owner and assert depositsCount is unchanged by withdraw and that withdraw reduces balance by at most requested amount.

        // Record intervening depositsCount and balance (no deposit attempt performed because address(c).call would violate call-shape rule)
        uint midDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint midBalance = address(c).balance;

        // Now, as owner (this contract deployed C), call withdraw on c as a top-level statement
        c.withdraw(withdrawAmount); if (__ESBMC_reverted()) return;

        // observe after
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // The general rule to assert:
        // - withdraw must not change depositsCount
        // - the balance decrease is at most withdrawAmount and not negative
        // So: afterDeposits == midDeposits and midBalance >= afterBalance and (midBalance - afterBalance) <= withdrawAmount
        assert(afterDeposits == midDeposits && midBalance >= afterBalance && (midBalance - afterBalance) <= withdrawAmount);
    }

    receive() external payable {}
}

