// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 sendAmount, uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        uint256 midDeposits;
        try c.depositsCount() returns (uint256 __r) { midDeposits = __r; } catch { return; }
        uint midBalance = address(c).balance;
        try c.withdraw(withdrawAmount) {} catch { return; }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterDeposits == midDeposits && midBalance >= afterBalance && (midBalance - afterBalance) <= withdrawAmount);
    }

    function testFuzz_run(uint256 sendAmount, uint256 withdrawAmount) public {
        _run(sendAmount, withdrawAmount);
    }

    receive() external payable {}
}
